"""Generate TypeScript classification and profile names from the Python contracts."""
from __future__ import annotations

import argparse
import json
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

from mnemotrace.categories import CATEGORIES  # noqa: E402
from mnemotrace.profile import SECTIONS  # noqa: E402

TARGETS = (
    "frontend/src/generated/memory-contract.ts",
    "clients/typescript/src/generated/memory-contract.ts",
)


def render() -> str:
    lines = [
        "// Generated by scripts/build_memory_contract.py.",
        "// Sources: mnemotrace/categories.py and mnemotrace/profile.py.",
    ]
    for name, type_name, values in (
        ("CATEGORIES", "Category", CATEGORIES),
        ("PROFILE_SECTIONS", "ProfileSection", SECTIONS),
    ):
        lines.extend(["", f"export const {name} = ["])
        lines.extend(f"  {json.dumps(value)}," for value in values)
        lines.extend([
            "] as const",
            f"export type {type_name} = (typeof {name})[number]",
        ])
    return "\n".join(lines) + "\n"


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="Report stale files without writing")
    args = parser.parse_args(argv)
    expected = render()
    stale = []
    for target in TARGETS:
        path = ROOT / target
        if path.is_file() and path.read_text(encoding="utf-8") == expected:
            continue
        if args.check:
            stale.append(target)
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(expected.encode("utf-8"))
    if stale:
        print("Stale memory contracts. Run python scripts/build_memory_contract.py")
        print("\n".join(stale))
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
